DROP PROCEDURE IF EXISTS dunegameplay.dune_kit_listing_lock;
DELIMITER //
CREATE DEFINER=`website`@`%` PROCEDURE dunegameplay.dune_kit_listing_lock(IN actual_buyer_uuid CHAR(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci, IN chosen_listing CHAR(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci) SQL SECURITY DEFINER READS SQL DATA
BEGIN
SELECT l.id AS listing_id,l.version AS listing_version,b.id AS blueprint_id,b.version AS blueprint_version,b.commerce_kind,seller.minecraft_uuid AS seller_uuid,a.username AS seller_name,l.clan_id,l.shop_type,l.price_cents,CAST(l.price_cents/100 AS DECIMAL(20,2)) AS price_dunemarks,b.name AS kit_name,b.color AS kit_color,b.lore_json AS kit_lore_json,b.quality,l.created_at,l.office_key,l.office_term,l.faction_id,CASE WHEN a.role IN ('owners','corestaff','web_net_admin','network_admin') THEN 1 ELSE 0 END AS server_authorized,CASE WHEN b.commerce_kind='personal_sale' AND u.user_id IS NOT NULL THEN 1 ELSE 0 END AS seller_tier_override,buyer.minecraft_uuid AS buyer_uuid,buyer.linked_at AS buyer_linked_at,seller.linked_at AS seller_linked_at
FROM website.site_kit_listings l JOIN website.site_kit_blueprints b ON b.id=l.blueprint_id AND b.version=l.blueprint_version AND b.active=1 JOIN website.site_accounts a ON a.id=b.owner_user_id JOIN website.site_game_links seller ON seller.user_id=b.owner_user_id LEFT JOIN website.site_kit_design_unlocks u ON u.user_id=a.id AND u.quality=b.quality JOIN website.site_game_links buyer ON buyer.minecraft_uuid=actual_buyer_uuid LEFT JOIN website.site_clans c ON c.id=l.clan_id AND c.active=1 LEFT JOIN website.site_clan_members m ON m.clan_id=c.id AND m.user_id=b.owner_user_id AND m.minecraft_uuid=seller.minecraft_uuid
WHERE l.id=chosen_listing AND l.active=1 AND l.published=1 AND l.price_cents BETWEEN 1 AND 100000000 AND (b.commerce_kind<>'personal_sale' OR l.price_cents>=CASE b.quality WHEN 'common' THEN 10000 WHEN 'uncommon' THEN 20000 WHEN 'rare' THEN 40000 WHEN 'very_rare' THEN 80000 WHEN 'legendary' THEN 160000 ELSE 100000001 END) AND ((b.commerce_kind='personal_sale' AND ((l.shop_type='player' AND l.clan_id IS NULL) OR (l.shop_type='clan' AND m.clan_role IN ('owner','officer')))) OR (b.commerce_kind='official_sale' AND l.shop_type='official' AND l.clan_id IS NULL AND l.office_key IS NOT NULL AND l.office_term IS NOT NULL AND l.faction_id IS NULL) OR (b.commerce_kind='faction_sale' AND l.shop_type='faction' AND l.clan_id IS NULL AND l.faction_id IN ('fremen','harkonnen','corrino','atreides','ordos') AND l.office_key IS NOT NULL AND l.office_term IS NOT NULL) OR (b.commerce_kind='server_sale' AND l.shop_type='server' AND l.clan_id IS NULL AND a.role IN ('owners','corestaff','web_net_admin','network_admin'))) FOR SHARE;
END//
DELIMITER ;
GRANT EXECUTE ON PROCEDURE dunegameplay.dune_kit_listing_lock TO `website`@`%`,`dunegameplay`@`127.0.0.1`;

DROP PROCEDURE IF EXISTS dunegameplay.dune_kit_catalogue;
DELIMITER //
CREATE DEFINER=`website`@`%` PROCEDURE dunegameplay.dune_kit_catalogue() SQL SECURITY DEFINER READS SQL DATA
BEGIN
SELECT l.id AS listing_id,l.version AS listing_version,b.id AS blueprint_id,b.version AS blueprint_version,b.commerce_kind,seller.minecraft_uuid AS seller_uuid,a.username AS seller_name,l.clan_id,l.shop_type,l.price_cents,CAST(l.price_cents/100 AS DECIMAL(20,2)) AS price_dunemarks,b.name AS kit_name,b.color AS kit_color,b.lore_json AS kit_lore_json,b.quality,l.created_at,l.office_key,l.office_term,l.faction_id,CASE WHEN a.role IN ('owners','corestaff','web_net_admin','network_admin') THEN 1 ELSE 0 END AS server_authorized,CASE WHEN b.commerce_kind='personal_sale' AND u.user_id IS NOT NULL THEN 1 ELSE 0 END AS seller_tier_override
FROM website.site_kit_listings l JOIN website.site_kit_blueprints b ON b.id=l.blueprint_id AND b.version=l.blueprint_version AND b.active=1 JOIN website.site_accounts a ON a.id=b.owner_user_id JOIN website.site_game_links seller ON seller.user_id=b.owner_user_id LEFT JOIN website.site_kit_design_unlocks u ON u.user_id=a.id AND u.quality=b.quality  LEFT JOIN website.site_clans c ON c.id=l.clan_id AND c.active=1 LEFT JOIN website.site_clan_members m ON m.clan_id=c.id AND m.user_id=b.owner_user_id AND m.minecraft_uuid=seller.minecraft_uuid
WHERE l.active=1 AND l.published=1 AND l.price_cents BETWEEN 1 AND 100000000 AND (b.commerce_kind<>'personal_sale' OR l.price_cents>=CASE b.quality WHEN 'common' THEN 10000 WHEN 'uncommon' THEN 20000 WHEN 'rare' THEN 40000 WHEN 'very_rare' THEN 80000 WHEN 'legendary' THEN 160000 ELSE 100000001 END) AND ((b.commerce_kind='personal_sale' AND ((l.shop_type='player' AND l.clan_id IS NULL) OR (l.shop_type='clan' AND m.clan_role IN ('owner','officer')))) OR (b.commerce_kind='official_sale' AND l.shop_type='official' AND l.clan_id IS NULL AND l.office_key IS NOT NULL AND l.office_term IS NOT NULL AND l.faction_id IS NULL) OR (b.commerce_kind='faction_sale' AND l.shop_type='faction' AND l.clan_id IS NULL AND l.faction_id IN ('fremen','harkonnen','corrino','atreides','ordos') AND l.office_key IS NOT NULL AND l.office_term IS NOT NULL) OR (b.commerce_kind='server_sale' AND l.shop_type='server' AND l.clan_id IS NULL AND a.role IN ('owners','corestaff','web_net_admin','network_admin'))) ORDER BY l.created_at DESC,l.id LIMIT 500;
END//
DELIMITER ;
GRANT EXECUTE ON PROCEDURE dunegameplay.dune_kit_catalogue TO `website`@`%`,`dunegameplay`@`127.0.0.1`;
